import "../../../../scripts/db-safety/test-entry.cjs";
import test from "node:test";
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { pathToFileURL } from "node:url";
import { db } from "@/lib/db";

/**
 * Seed for the T029/T031 rehearsal (`release:phase029-backfill`). Runs on the 23-migration database BEFORE migration 24, through the baseline
 * client generated by `g2:generate` (same pattern as g2-baseline.test.ts): every Dataset is created the way historical data exists, unresolved.
 * Only synthetic rows (ids `bf-*`, `sc-*`) are written; nothing here touches any other database.
 */
const receipt = JSON.parse(readFileSync(process.env.DB_SAFETY_RECEIPT!, "utf8"));
const BUCKET = "bf-bucket";
type Case = { id: string; assets?: Asset[]; primary?: string; archived?: boolean; deleted?: boolean; job?: boolean };
type Asset = { modality?: string; child?: string | null; storageKey?: string | null; provider?: string; bucket?: string; size?: number | null; etag?: string; deleted?: boolean };

const MIME: Record<string, string> = { IMAGE: "image/png", VIDEO: "video/mp4", AUDIO: "audio/wav", TEXT: "text/plain" };
const CHILD: Record<string, object> = { imageAsset: { create: { exif: {} } }, videoAsset: { create: { metadata: {} } }, audioAsset: { create: { metadata: {} } }, textAsset: { create: { tokenization: {}, metadata: {} } } };
const childFor = (modality: string) => `${modality.toLowerCase()}Asset`;

const CASES: Case[] = [
  // Eligible SINGLE datasets (the main happy path)
  { id: "bf-image", assets: [{}, {}] },
  { id: "bf-video", assets: [{ modality: "VIDEO" }] },
  { id: "bf-audio", assets: [{ modality: "AUDIO" }] },
  { id: "bf-text", assets: [{ modality: "TEXT" }] },
  { id: "bf-image-etag", assets: [{ etag: "etag-ok" }] },
  { id: "bf-primary-conflict", primary: "IMAGE", assets: [{ modality: "AUDIO" }] }, // legacy primaryModality disagrees with the Assets
  { id: "bf-primary-agree", primary: "VIDEO", assets: [{ modality: "VIDEO" }] },
  // Never candidates
  { id: "bf-empty" }, { id: "bf-empty-primary", primary: "IMAGE" }, { id: "bf-empty-resolved" },
  { id: "bf-mixed", assets: [{}, { modality: "AUDIO" }] }, { id: "bf-mixed-primary", primary: "AUDIO", assets: [{}, { modality: "AUDIO" }] },
  { id: "bf-no-subtype", assets: [{ child: null }] },
  { id: "bf-subtype-mismatch", assets: [{ child: "videoAsset" }] },
  { id: "bf-no-storage", assets: [{ storageKey: null }] },
  { id: "bf-external", assets: [{ provider: "EXTERNAL" }] },
  { id: "bf-size-unrecorded", assets: [{ size: null }] },
  { id: "bf-size-mismatch", assets: [{}] },
  { id: "bf-object-missing", assets: [{}] },
  { id: "bf-etag-mismatch", assets: [{ etag: "etag-recorded" }] },
  { id: "bf-bucket-foreign", assets: [{ bucket: "foreign-bucket" }] },
  { id: "bf-soft-deleted", assets: [{}, { deleted: true }] },
  { id: "bf-inflight", assets: [{}], job: true },
  { id: "bf-archived", assets: [{}], archived: true },
  { id: "bf-deleted", assets: [{}], deleted: true },
  // Scenario datasets (each is used by exactly one rehearsal scenario)
  { id: "sc-stale-fence", assets: [{}] }, { id: "sc-changed-evidence", assets: [{}] }, { id: "sc-object-changed", assets: [{}] },
  { id: "sc-atomic-claim", assets: [{}] }, { id: "sc-atomic-assign", assets: [{}] },
  { id: "sc-int-1", assets: [{}] }, { id: "sc-int-2", assets: [{}] }, { id: "sc-int-3", assets: [{}] },
  { id: "sc-abort-1", assets: [{}] }, { id: "sc-abort-2", assets: [{}] },
  { id: "sc-conc-1", assets: [{}] }, { id: "sc-conc-2", assets: [{}] }, { id: "sc-conc-3", assets: [{ modality: "VIDEO" }] },
  { id: "sc-race", assets: [{}, {}] },
];

test("historical unresolved datasets for the backfill rehearsal are seeded on the 23-migration baseline", async () => {
  const { PrismaClient } = await import(pathToFileURL(join(dirname(receipt.config), "baseline-client/client.ts")).href);
  const baseline = new PrismaClient();
  try {
    await baseline.$transaction(async (tx: typeof baseline) => {
      await tx.user.create({ data: { id: "bf-owner", email: "bf-owner@test.invalid", role: "MANAGER" }, select: { id: true } });
      for (const spec of CASES) {
        await tx.dataset.create({ data: {
          id: spec.id, name: spec.id, ownerId: "bf-owner", metadata: { workflowStatus: "COMPLETED" },
          ...(spec.primary ? { primaryModality: spec.primary } : {}), ...(spec.archived ? { archivedAt: new Date() } : {}), ...(spec.deleted ? { deletedAt: new Date() } : {}),
        }, select: { id: true } });
        let index = 0;
        for (const asset of spec.assets ?? []) {
          index += 1;
          const modality = asset.modality ?? "IMAGE";
          const id = `${spec.id}-a${index}`;
          const child = asset.child === undefined ? childFor(modality) : asset.child;
          await tx.asset.create({ data: {
            id, datasetId: spec.id, filename: `${id}.bin`, relativePath: `${id}.bin`, sourceFingerprint: `bf-fixture:${id}`, modality, mimeType: MIME[modality],
            sizeBytes: asset.size === null ? null : BigInt(asset.size ?? 10 + index),
            storageProvider: asset.provider ?? "MINIO", storageBucket: asset.bucket ?? BUCKET, storageKey: asset.storageKey === null ? null : `bf/${id}`,
            ...(asset.etag ? { sourceEtag: asset.etag } : {}), ...(asset.deleted ? { deletedAt: new Date() } : {}),
            ...(child ? CHILD[child] ? { [child]: CHILD[child] } : {} : {}),
          }, select: { id: true } });
        }
        if (spec.job) await tx.job.create({ data: { id: `bf-job-${spec.id}`, datasetId: spec.id, createdById: "bf-owner", type: "IMPORT_DATASET", status: "QUEUED" }, select: { id: true } });
      }
    });
  } finally { await baseline.$disconnect(); await db.$disconnect(); }
});
